USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_Workflow_Advance @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@ExpectedStage VARCHAR(40),@ActionType VARCHAR(50),@ActorRole VARCHAR(40),@ToStage VARCHAR(40),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL
AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;BEGIN TRY BEGIN TRAN;
 DECLARE @stage VARCHAR(40),@rule BIGINT,@owner VARCHAR(30),@concernId BIGINT,@headerStatus VARCHAR(40);
 SELECT @stage=w.CURRENT_STAGE,@rule=w.WORKFLOW_RULE_ID,@owner=w.CURRENT_OWNER_EMPLOYEE_ID,@concernId=r.CONCERN_DIVISION_ID,@headerStatus=h.CURRENT_STATUS FROM dbo.WORKFLOW_INSTANCE w WITH(UPDLOCK,HOLDLOCK)JOIN dbo.REQUISITION_HEADER h WITH(UPDLOCK,HOLDLOCK)ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.COMPLETED_DATE IS NULL;
 IF @stage IS NULL THROW 51001,'Active workflow not found.',1;IF @headerStatus<>'IN_WORKFLOW'THROW 51003,'Requisition is not in workflow.',1;IF @stage<>@ExpectedStage THROW 51003,'Invalid workflow stage.',1;IF @owner IS NOT NULL AND @owner<>@ActorEmployeeId THROW 51002,'Request is owned by another employee.',1;
 IF @ExpectedStage='PROCUREMENT_AUTHORITY'AND NOT EXISTS(SELECT 1 FROM dbo.PROC_AUTHORITY WHERE EMPLOYEE_ID=@ActorEmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))THROW 51002,'Actor is not an active Procurement Authority.',1;
 IF @ExpectedStage='CONCERN_DIVISION'AND NOT EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_OFFICIAL WHERE CONCERN_DIVISION_ID=@concernId AND EMPLOYEE_ID=@ActorEmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))THROW 51002,'Actor is not an active Concern Official.',1;
 IF @ExpectedStage='CONCERN_AUTHORITY'AND NOT EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_AUTHORITY WHERE CONCERN_DIVISION_ID=@concernId AND EMPLOYEE_ID=@ActorEmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME())AND(EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME())))THROW 51002,'Actor is not an active Concern Authority.',1;
 IF @ExpectedStage IN('PROCUREMENT_AUTHORITY','CONCERN_DIVISION','CONCERN_AUTHORITY')AND NOT EXISTS(SELECT 1 FROM dbo.REQUISITION_ASSIGNMENT WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1 AND ASSIGNMENT_TYPE=CASE @ExpectedStage WHEN'PROCUREMENT_AUTHORITY'THEN'PROCUREMENT_AUTHORITY_POOL'WHEN'CONCERN_DIVISION'THEN'CONCERN_OFFICIAL'ELSE'CONCERN_AUTHORITY'END)THROW 51003,'No current assignment exists for the workflow stage.',1;
 DECLARE @org BIGINT=(SELECT ORG_UNIT_ID FROM dbo.CONCERN_DIVISION_SETUP WHERE CONCERN_DIVISION_ID=@concernId AND IS_ACTIVE=1);IF @ToStage IN('CONCERN_DIVISION','CONCERN_AUTHORITY')AND @org IS NULL THROW 51000,'Concern Division organization is not configured.',1;
 UPDATE dbo.REQUISITION_ASSIGNMENT SET IS_CURRENT=0,RELEASED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND IS_CURRENT=1;
 UPDATE dbo.WORKFLOW_INSTANCE SET CURRENT_STAGE=@ToStage,CURRENT_OWNER_TYPE=CASE WHEN @ToStage IN('READY_FOR_PROCUREMENT','END')THEN'NONE'WHEN @ToStage IN('CONCERN_DIVISION','CONCERN_AUTHORITY')THEN'ORG_UNIT'ELSE'ROLE_POOL'END,CURRENT_OWNER_EMPLOYEE_ID=NULL,CURRENT_OWNER_ORG_UNIT_ID=CASE WHEN @ToStage IN('CONCERN_DIVISION','CONCERN_AUTHORITY')THEN @org END,CURRENT_STATUS=CASE WHEN @ToStage IN('READY_FOR_PROCUREMENT','END')THEN'COMPLETED'ELSE'PENDING'END,COMPLETED_DATE=CASE WHEN @ToStage IN('READY_FOR_PROCUREMENT','END')THEN SYSUTCDATETIME()END,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId AND COMPLETED_DATE IS NULL;
 IF @ToStage NOT IN('READY_FOR_PROCUREMENT','END')INSERT dbo.REQUISITION_ASSIGNMENT(REQUISITION_ID,ASSIGNMENT_TYPE,ASSIGNED_TO_ORG_UNIT_ID,CREATED_BY)VALUES(@RequisitionId,CASE @ToStage WHEN'CONCERN_DIVISION'THEN'CONCERN_OFFICIAL'WHEN'CONCERN_AUTHORITY'THEN'CONCERN_AUTHORITY'ELSE'PROCUREMENT_AUTHORITY_POOL'END,CASE WHEN @ToStage IN('CONCERN_DIVISION','CONCERN_AUTHORITY')THEN @org END,@ActorEmployeeId);
 INSERT dbo.APPROVAL_ACTION(REQUISITION_ID,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,ACTION_ROLE,FROM_STAGE,TO_STAGE,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@ActionType,@ActorEmployeeId,@ActorRole,@stage,@ToStage,@Remarks,@BatchReferenceId);INSERT dbo.WORKFLOW_HISTORY(REQUISITION_ID,WORKFLOW_RULE_ID,FROM_STAGE,TO_STAGE,ACTION_TYPE,ACTION_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@RequisitionId,@rule,@stage,@ToStage,@ActionType,@ActorEmployeeId,@Remarks,@BatchReferenceId);
 IF @ToStage='READY_FOR_PROCUREMENT'BEGIN DECLARE @sid BIGINT=(SELECT STATUS_ID FROM dbo.PROCUREMENT_STATUS_MASTER WHERE STATUS_CODE='READY_FOR_PROCUREMENT'AND IS_ACTIVE=1);IF @sid IS NULL THROW 51000,'READY_FOR_PROCUREMENT status is not configured.',1;UPDATE dbo.REQUISITION_HEADER SET CURRENT_STATUS='READY_FOR_PROCUREMENT',MODIFIED_BY=@ActorEmployeeId,MODIFIED_DATE=SYSUTCDATETIME()WHERE REQUISITION_ID=@RequisitionId;INSERT dbo.PROCUREMENT_TRACKING(REQUISITION_ID,CURRENT_STATUS_ID)VALUES(@RequisitionId,@sid);DECLARE @pid BIGINT=SCOPE_IDENTITY();INSERT dbo.PROCUREMENT_STATUS_HISTORY(PROCUREMENT_ID,STATUS_ID,CHANGED_BY_EMPLOYEE_ID,REMARKS,BATCH_REFERENCE_ID)VALUES(@pid,@sid,@ActorEmployeeId,@Remarks,@BatchReferenceId);END;
 COMMIT;SELECT'000'RESULT_CODE,N'Success'RESULT_MESSAGE,@RequisitionId ENTITY_ID,@ToStage REFERENCE_NO;
END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;SELECT CASE ERROR_NUMBER()WHEN 51000 THEN'001'WHEN 51001 THEN'002'WHEN 51002 THEN'003'WHEN 51003 THEN'004'WHEN 2601 THEN'005'WHEN 2627 THEN'005'ELSE'999'END RESULT_CODE,ERROR_MESSAGE()RESULT_MESSAGE,@RequisitionId ENTITY_ID,NULL REFERENCE_NO;END CATCH END;
GO
